<script setup lang="ts">import {AlertCircle,LoaderCircle} from 'lucide-vue-next';defineProps<{error?:string;loading?:boolean;empty?:string}>();defineEmits<{retry:[]}>()</script>
<template><div v-if="loading" class="notice loading" role="status"><LoaderCircle :size="22" class="spin"/><span>正在连接知识的线索…</span></div><div v-else-if="error" class="notice error" role="alert"><AlertCircle :size="22"/><div><strong>这一步暂时没有完成</strong><p>{{error}}</p><button class="text-button" @click="$emit('retry')">重新尝试 →</button></div></div><div v-else-if="empty" class="notice empty"><span class="empty-orbit">◎</span><p>{{empty}}</p><slot/></div></template>
